//go:build linux

package launchguard

import (
	"bytes"
	"encoding/binary"
	"errors"
	"io"
	"math"
	"unicode"

	"golang.org/x/sys/unix"
)

const (
	guardianReady uint32 = 1 + iota
	guardianAdmit
	guardianSettled
	guardianFailed
)

// Credentials are generated by the kernel for every handoff message, after
// the sender's final identity drop. No descriptor transfer is accepted here.
func guardianProtocolSocket(fd int) error {
	return unix.SetsockoptInt(fd, unix.SOL_SOCKET, unix.SO_PASSCRED, 1)
}

func sendGuardianMessage(fd int, phase uint32, status uint32) error {
	if phase < guardianReady || phase > guardianFailed || (phase == guardianFailed && status != 1) || ((phase == guardianReady || phase == guardianAdmit) && status != 0) || status > 255 {
		return errors.New("invalid guardian handoff message")
	}
	var raw [24]byte
	copy(raw[:], "PWGHAND1")
	binary.LittleEndian.PutUint32(raw[8:], 1)
	binary.LittleEndian.PutUint32(raw[12:], phase)
	binary.LittleEndian.PutUint32(raw[16:], status)
	for {
		n, err := unix.SendmsgN(fd, raw[:], nil, nil, unix.MSG_NOSIGNAL)
		if errors.Is(err, unix.EINTR) {
			continue
		}
		if err != nil {
			return err
		}
		if n != len(raw) {
			return errors.New("incomplete guardian handoff send")
		}
		return nil
	}
}

type guardianNotice struct{ phase, status uint32 }

// A privileged stage that stops before handoff prints nothing itself; it sends
// its reason here so the bootstrap's refusal names the actual cause.
const (
	stageRefusalMagic = "PWGSREF1"
	stageRefusalLimit = 512
)

func sendStageRefusal(fd int, reason error) {
	text := []byte(reason.Error())
	if len(text) > stageRefusalLimit {
		text = text[:stageRefusalLimit]
	}
	packet := append([]byte(stageRefusalMagic), text...)
	_, _ = unix.SendmsgN(fd, packet, nil, nil, unix.MSG_NOSIGNAL|unix.MSG_DONTWAIT)
}

// stageRefusal reads a refusal frame as printable text.
func stageRefusal(raw []byte) (string, bool) {
	if !bytes.HasPrefix(raw, []byte(stageRefusalMagic)) {
		return "", false
	}
	text := []rune(string(raw[len(stageRefusalMagic):]))
	for index, r := range text {
		if !unicode.IsPrint(r) {
			text[index] = '?'
		}
	}
	return string(text), true
}

type stageRefusalError struct{ reason string }

func (err *stageRefusalError) Error() string { return "protected setup refused: " + err.reason }

// receiveHandoffPacket admits the stage's own refusal, sent while it is still
// root, beside the guardian's notice, sent after the drop to the caller.
func receiveHandoffPacket(fd int, pid int, caller Identity) (raw []byte, root bool, err error) {
	var credentials *unix.Ucred
	raw, credentials, err = receivePacket(fd, pid, len(stageRefusalMagic)+stageRefusalLimit)
	if err != nil {
		return nil, false, err
	}
	switch {
	case credentials.Uid == caller.UID && credentials.Gid == caller.GID:
		return raw, false, nil
	case credentials.Uid == 0 && credentials.Gid == 0:
		return raw, true, nil
	}
	return nil, false, errors.New("guardian handoff sender differs from selected process")
}

func receiveGuardianPacket(fd int, pid int, caller Identity, limit int) ([]byte, error) {
	raw, credentials, err := receivePacket(fd, pid, limit)
	if err != nil {
		return nil, err
	}
	if credentials.Uid != caller.UID || credentials.Gid != caller.GID {
		return nil, errors.New("guardian handoff sender differs from selected process")
	}
	return raw, nil
}

func receivePacket(fd int, pid int, limit int) ([]byte, *unix.Ucred, error) {
	raw := make([]byte, limit+1)
	control := make([]byte, unix.CmsgSpace(unix.SizeofUcred))
	for {
		n, oobn, flags, _, err := unix.Recvmsg(fd, raw, control, unix.MSG_CMSG_CLOEXEC|unix.MSG_DONTWAIT)
		if errors.Is(err, unix.EINTR) {
			continue
		}
		if err != nil {
			return nil, nil, err
		}
		// Linux can echo the requested close-on-exec flag even on EOF.
		if n == 0 && oobn == 0 && (flags == 0 || flags == unix.MSG_CMSG_CLOEXEC) {
			return nil, nil, io.EOF
		}
		messages, controlErr := unix.ParseSocketControlMessage(control[:oobn])
		// Close any injected rights before rejecting their control shape.
		for _, message := range messages {
			if message.Header.Level == unix.SOL_SOCKET && message.Header.Type == unix.SCM_RIGHTS {
				rights, _ := unix.ParseUnixRights(&message)
				for _, right := range rights {
					_ = unix.Close(right)
				}
			}
		}
		if flags&(unix.MSG_TRUNC|unix.MSG_CTRUNC) != 0 || n > limit || controlErr != nil || len(messages) != 1 || messages[0].Header.Level != unix.SOL_SOCKET || messages[0].Header.Type != unix.SCM_CREDENTIALS {
			return nil, nil, errors.New("invalid guardian handoff control shape")
		}
		credentials, err := unix.ParseUnixCredentials(&messages[0])
		if err != nil || int(credentials.Pid) != pid {
			return nil, nil, errors.New("guardian handoff sender differs from selected process")
		}
		return raw[:n], credentials, nil
	}
}

func receiveGuardianNotice(fd int, pid int, caller Identity) (guardianNotice, error) {
	raw, err := receiveGuardianPacket(fd, pid, caller, 24)
	if err != nil {
		return guardianNotice{}, err
	}
	return decodeGuardianNotice(raw)
}

func decodeGuardianNotice(raw []byte) (guardianNotice, error) {
	if len(raw) != 24 {
		return guardianNotice{}, errors.New("invalid guardian handoff frame length")
	}

	if string(raw[:8]) != "PWGHAND1" || binary.LittleEndian.Uint32(raw[8:]) != 1 || binary.LittleEndian.Uint32(raw[20:]) != 0 {
		return guardianNotice{}, errors.New("invalid guardian handoff frame")
	}
	phase := binary.LittleEndian.Uint32(raw[12:])
	status := binary.LittleEndian.Uint32(raw[16:])
	if phase < guardianReady || phase > guardianFailed || (phase == guardianFailed && status != 1) || status > 255 || ((phase == guardianReady || phase == guardianAdmit) && status != 0) {
		return guardianNotice{}, errors.New("invalid guardian handoff status")
	}
	return guardianNotice{phase: phase, status: status}, nil
}

// guardianPollDescriptor preserves descriptor identity across the kernel poll ABI.
func guardianPollDescriptor(fd uintptr) (int32, error) {
	if fd > math.MaxInt32 {
		return -1, errors.New("guardian descriptor exceeds poll ABI width")
	}
	return int32(fd), nil
}

// A signal may interrupt a zero-timeout pidfd observation before the kernel reports readiness.
func pollGuardianNow(fds []unix.PollFd, poll func([]unix.PollFd, int) (int, error)) error {
	for {
		_, err := poll(fds, 0)
		if !errors.Is(err, unix.EINTR) {
			return err
		}
	}
}
